#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int n;
vector<ll> a;
vector<int> mark;
int ans;

bool isp(ll x) {
    if (x < 2) return false;
    for (ll i = 2; i <= x / i; ++i) {
        if (x % i == 0) return false;
    }
    return true;
}

int cal(ll x) {
    int cnt = 0;
    for (ll i = 2; i <= x / i; ++i) {
        while (x % i == 0) {
            ++cnt;
            x /= i;
        }
    }
    return cnt + (x != 1);
}

int calc(ll value, ll divisor) {
    if (isp(value)) return 0;
    return cal(value / divisor);
}

void dfs(int pos, int cost) {
    if (cost >= ans) return;
    if (pos < 0) {
        ans = cost;
        return;
    }

    uint64_t up = 1ULL << pos;
    for (uint64_t mask = 0; mask < up; ++mask) {
        bool ok = true;
        ll product = 1;

        for (int j = 0; j < pos; ++j) {
            if (mask & (1ULL << j)) {
                if (mark[j] || a[j] <= 0 ||
                    product > a[pos] / a[j]) {
                    ok = false;
                    break;
                }

                product *= a[j];
                if (a[pos] % product != 0) {
                    ok = false;
                    break;
                }
            }
        }

        if (!ok) continue;

        for (int j = 0; j < pos; ++j) {
            if (mask & (1ULL << j)) mark[j] = 1;
        }

        dfs(pos - 1, cost + 1 + calc(a[pos], product));

        for (int j = 0; j < pos; ++j) {
            if (mask & (1ULL << j)) mark[j] = 0;
        }
    }
}

