    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    a.resize(n);
    mark.assign(n, 0);

    for (ll &value : a) cin >> value;
    sort(a.begin(), a.end());

    ans = INT_MAX;
    dfs(n - 1, 1);

    if (n > 0) {
        ll product = 1;
        bool ok = true;

        for (int i = 0; i < n - 1; ++i) {
            if (a[i] <= 0 || product > a[n - 1] / a[i]) {
                ok = false;
                break;
            }

            product *= a[i];
            if (a[n - 1] % product != 0) {
                ok = false;
                break;
            }
        }

        if (ok) {
            dfs(n - 2, 1 + calc(a[n - 1], product));
        }
    }

    cout << ans << '\n';
